set -euo pipefail
printf '%s' '' | base64 -d | tar -xzf - -C /opt/brigada-core-src
cd /opt/brigada-core-src
./gradlew --no-daemon clean build
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
SRC=/opt/brigada-core-src/build/libs/brigada-core-0.1.0.jar
DST=/opt/minecraft/server/mods/brigada-core-0.1.0.jar
install -d -m 0755 /opt/minecraft/server/backups
cp -a "$DST" "/opt/minecraft/server/backups/brigada-core-0.1.0-$STAMP.jar"
install -m 0644 "$SRC" "$DST"
PROP=/opt/minecraft/server/server.properties
sed -i '/^resource-pack=/d;/^resource-pack-sha1=/d;/^resource-pack-id=/d;/^resource-pack-prompt=/d;/^require-resource-pack=/d' "$PROP"
printf '%s\n' 'resource-pack=http://143.246.197.187:8088/Brigada13-26.3-snapshot-9.zip' 'resource-pack-sha1=9252797b4ec1056975af2111b1e3f01791e3e819' 'resource-pack-id=b13b13b1-3b13-4b13-8b13-b13b13b13b13' 'resource-pack-prompt={"text":"Скачать оформление Бригады №13?","color":"gold","bold":true}' 'require-resource-pack=false' >> "$PROP"
systemctl restart minecraft.service
sleep 70
printf 'SERVICES\n'
systemctl is-active minecraft.service
systemctl is-active brigada-pack.service
printf '\nPORTS\n'
ss -ltnp | grep -E ':25565|:8088' || true
printf '\nHASHES\n'
sha256sum "$DST"
sha1sum /opt/minecraft/resourcepack/Brigada13-26.3-snapshot-9.zip
printf '\nPROPERTIES\n'
grep -E '^(resource-pack|require-resource-pack)' "$PROP"
printf '\nLOG\n'
journalctl -u minecraft.service -n 220 --no-pager | grep -E 'Brigada|Loaded 120|Done|ERROR|Exception|Failed|dialog|font|resource' | tail -n 100 || true
